SELECT COUNT(DISTINCT a.hadm_id) AS total_admissions FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'M' AND p.anchor_age = 77 AND p.anchor_year_group BETWEEN 72 AND 82 AND d.icd_code = 'I210' AND a.dischtime IS NOT NULL AND t.eventtype = 'transfer' AND a.insurance = 'Medicare';